import type {
  BulgarianDisplaySource,
  ClinicalDisplayDomain,
  ClinicalDisplayTerm,
  LocalizedClinicalText,
} from "./types"
import { clinicalDisplayReviewStatus } from "./review"

function text(en: string, bg: string): LocalizedClinicalText {
  return { en, bg }
}

function term(
  domain: ClinicalDisplayDomain,
  code: string,
  en: string,
  bg: string,
  options: {
    shortEn?: string
    shortBg?: string
    descriptionEn?: string
    descriptionBg?: string
    aliases?: readonly string[]
    bgSource?: BulgarianDisplaySource
  } = {},
): ClinicalDisplayTerm {
  return {
    domain,
    code,
    label: text(en, bg),
    ...(options.shortEn && options.shortBg
      ? { shortLabel: text(options.shortEn, options.shortBg) }
      : {}),
    ...(options.descriptionEn && options.descriptionBg
      ? { description: text(options.descriptionEn, options.descriptionBg) }
      : {}),
    ...(options.aliases?.length ? { aliases: options.aliases } : {}),
    reviewStatus: clinicalDisplayReviewStatus(domain, code),
    bgSource: options.bgSource ?? (en === bg ? "international" : "translated"),
  }
}

